function mat_lits(x: HTerm): Row[] {
  const ws: Row[] = [];
  // Compare the old coverage keys without materializing their JSON strings.
  // Lowering is retained: binder names/levels and substituted Vars must have
  // exactly the old representation, rather than a wider semantic equality.
  const same = (a: unknown, b: unknown): boolean => {
    // All tagged Ann values here originate in the lowered term, not user data.
    if (a && typeof a === "object" && "$" in a && a.$ === "Ann") {
      a = Bend.term_strip(a as Bend.LTerm);
    }
    if (b && typeof b === "object" && "$" in b && b.$ === "Ann") {
      b = Bend.term_strip(b as Bend.LTerm);
    }
    if (typeof a === "number" && !Number.isFinite(a)) a = null;
    if (typeof b === "number" && !Number.isFinite(b)) b = null;
    if (a === b) return true;
    if (a === null || b === null || typeof a !== typeof b) return false;
    if (typeof a !== "object") return false;
    if (Array.isArray(a)) {
      if (!Array.isArray(b) || a.length !== b.length) return false;
      for (let i = 0; i < a.length; i++) {
        // JSON arrays retain omitted values as null (including holes).
        const av = a[i], bv = b[i];
        const ax = av === undefined || typeof av === "function" || typeof av === "symbol";
        const bx = bv === undefined || typeof bv === "function" || typeof bv === "symbol";
        if (!same(ax ? null : av, bx ? null : bv)) return false;
      }
      return true;
    }
    if (Array.isArray(b)) return false;
    // Keep property order: even equal maps with different insertion order had
    // different keys. Undefined object fields and spans were omitted entirely.
    const ar = a as Record<string, unknown>;
    const br = b as Record<string, unknown>;
    const ak = Object.keys(ar).filter(k => k !== "s" && ar[k] !== undefined
      && typeof ar[k] !== "function" && typeof ar[k] !== "symbol");
    const bk = Object.keys(br).filter(k => k !== "s" && br[k] !== undefined
      && typeof br[k] !== "function" && typeof br[k] !== "symbol");
    return ak.length === bk.length && ak.every((k, i) => k === bk[i] && same(ar[k], br[k]));
  };
  const walk = (t: HTerm, j: number, n: number,
    cov: ((w: Of<"Ctr">) => HTerm) | null) => {
    const h = mat_arms(t).arms[0]?.[1];
    if (h && j === 32) {
      ws.push([h, j, n, 0]);
      return;
    }
    const { arms, end } = mat_arms(h ?? t);
    const inst = (w: Of<"Ctr">) => (h ? w.x : [w])
      .reduce((f, a) => Bend.term_apply(f, a), end);
    const w = Bend.Ctr("WCon", [probe("b"), probe("t")]) as Of<"Ctr">;
    const own = arms.length < 2 && (!cov
      || !same(Bend.term_lower(cov(w)), Bend.term_lower(inst(w))));
    const sub = own ? inst : cov;
    for (const [k, a] of arms) {
      walk(a, j + 1, n + (k === "True" ? 2 ** j : 0), sub && ((v) =>
        sub(Bend.Ctr("WCon", [Bend.Ctr(k, []), v]) as Of<"Ctr">)));
    }
    if (own) {
      ws.push([end, j, n, h ? 2 : 1]);
    }
  };
  walk(mat_arms(x).arms[0][1], 0, 0, null);
  return ws;
}
